                    <div style={{ width: 32, height: 32, borderRadius: "50%", background: "linear-gradient(135deg, " + ag.color + "40, " + ag.color + "15)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 700, color: ag.color }}>{a.initials}</div>
